import os
import tempfile
import zipfile
from pathlib import Path


def output_dir() -> Path:
    path = Path(os.getenv("OUTPUT_DIR", "./generated_certificates")).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path


def certificate_path(job_id: str, file_name: str) -> Path:
    # Names are generated by the server, then resolved under the configured output directory.
    if Path(file_name).name != file_name or not file_name.endswith(".pdf"):
        raise ValueError("Invalid certificate filename")
    root = output_dir()
    result = (root / job_id / file_name).resolve()
    if root not in result.parents:
        raise ValueError("Invalid certificate path")
    return result


def build_zip(paths: list[tuple[Path, str]]) -> Path:
    root = output_dir()
    fd, name = tempfile.mkstemp(prefix="certificates-", suffix=".zip", dir=root)
    os.close(fd)
    archive_path = Path(name)
    try:
        with zipfile.ZipFile(archive_path, "w", zipfile.ZIP_DEFLATED) as archive:
            for path, filename in paths:
                archive.write(path, arcname=filename)
        return archive_path
    except Exception:
        archive_path.unlink(missing_ok=True)
        raise
